import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class CrystalCache<K, V> {

    private final Map<K, V> relics;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public CrystalCache(Map<K, V> relics) {
        this.relics = relics;
    }

    public V put(K key, V value) {
        lock.writeLock().lock();
        try {
            return relics.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V remove(K key) {
        lock.writeLock().lock();
        try {
            return relics.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        lock.writeLock().lock();
        try {
            relics.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            relics.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V get(K key) {
        lock.readLock().lock();
        try {
            return relics.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return relics.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return relics.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(K key) {
        lock.readLock().lock();
        try {
            return relics.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(V value) {
        lock.readLock().lock();
        try {
            return relics.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, String> initial = new HashMap<>();
        initial.put("amulet", "glowing");
        final CrystalCache<String, String> cache = new CrystalCache<>(initial);

        ExecutorService executor = Executors.newFixedThreadPool(3);

        executor.submit(() -> cache.put("orb", "shimmering"));
        executor.submit(() -> System.out.println("Seer1 sees: " + cache.get("amulet")));
        executor.submit(() -> System.out.println("Seer2 size: " + cache.size()));

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final cache size: " + cache.size());
    }
}

