public class PixieDustCounter {

    static class EnchantedCAS {
        private volatile int d;

        EnchantedCAS() {
            this(0);
        }

        EnchantedCAS(int initial) {
            this.d = initial;
        }

        // Synchronizing the compare-and-swap makes the "check current value,
        // then update" sequence atomic; combined with the volatile field this
        // gives plain reads of d a proper happens-before edge, removing the race.
        synchronized int compareAndSwap(int expected, int newValue) {
            int current = d;
            if (current == expected) {
                d = newValue;
            }
            return current;
        }

        int getD() {
            return d;
        }
    }

    private final EnchantedCAS cas = new EnchantedCAS();

    public int getDustLevel() {
        return cas.getD();
    }

    public void sprinkle() {
        int current;
        int actual;
        do {
            current = cas.getD();
            actual = cas.compareAndSwap(current, current + 1);
        } while (actual != current);
    }

    public static void main(String[] args) throws InterruptedException {
        final PixieDustCounter counter = new PixieDustCounter();

        Runnable sprinkleTask = () -> {
            for (int i = 0; i < 1000; i++) {
                counter.sprinkle();
            }
        };

        Thread t1 = new Thread(sprinkleTask);
        Thread t2 = new Thread(sprinkleTask);

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("Final dust level: " + counter.getDustLevel());
    }
}

