        if (result == null) {
            result = compute(i);
            cache = new OneValueCache(i, result);
        }
        return result;
    }

    public static void main(String[] args) throws InterruptedException {
        final CachingServlet servlet = new CachingServlet();
        ExecutorService executor = Executors.newFixedThreadPool(2);

