import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PrimeGenerator implements Runnable {

    private final List<BigInteger> primes = Collections.synchronizedList(new ArrayList<BigInteger>());

    // Volatile so the generator thread's polling loop reliably observes the
    // cancellation flag set by the controlling thread; this is what closes
    // the race JPF reported on "cancelled".
    private volatile boolean cancelled;

    @Override
    public void run() {
        BigInteger p = BigInteger.ONE;
        while (!cancelled) {
            p = p.nextProbablePrime();
            primes.add(p);
        }
    }

    public void cancel() {
        cancelled = true;
    }

    public List<BigInteger> get() {
        synchronized (primes) {
            return new ArrayList<>(primes);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        PrimeGenerator generator = new PrimeGenerator();
        ExecutorService executor = Executors.newSingleThreadExecutor();
        executor.submit(generator);

        try {
            Thread.sleep(1000);
        } finally {
            generator.cancel();
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Primes found: " + generator.get().size());
    }
}

